-- las-aventuras-de-tom-sawyer -- PARTE 3 de 5. Ejecuta las partes EN ORDEN.

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  40,
  'Los filibusteros acampan felizmente (2/3)',
  $lira$[{"type": "p", "text": "Después del desayuno se echaron a la sombra mientras Huck fumaba; luego emprendieron una expedición de reconocimiento por los bosques. Caminaron alegremente por encima de troncos pútridos, a través de embrollados matorrales, entre solemnes monarcas forestales, cubiertos desde la copa hasta el suelo de las colgantes insignias reales que formaban las plantas trepadoras. De vez en cuando se encontraban amables rincones tapizados de hierba y enjoyados de flores."}, {"type": "p", "text": "Hallaron muchas cosas con que deleitarse, pero nada que les asombrara. Descubrieron que la isla tenía unas tres millas de largo y un cuarto de milla de ancho, y que solo estaba separada de la ribera más próxima por un estrecho canal que apenas tendría doscientas yardas de anchura. Se bañaron casi cada hora, de modo que ya era cerca de media tarde cuando regresaron al campamento. Tenían demasiado apetito para pescar, pero devoraron el jamón frío, y luego se tendieron a la sombra a charlar. Pero la conversación pronto se volvió pausada y al final se extinguió. La calma y la solemnidad que reinaban en el bosque y la sensación de soledad comenzaron su obra en el espíritu de los muchachos. Empezaron a pensar. Una especie de nostalgia indefinida iba envolviéndolos. Pronto cobró una forma opaca; era la nostalgia del hogar. Hasta Finn Mano Roja recordaba los peldaños de las entradas y los barriles vacíos. Pero los tres estaban avergonzados de su debilidad, y ninguno tenía el valor de manifestar su pensamiento. Desde hacía un rato, los muchachos oían un sonido peculiar en la lejanía, como le ocurre a uno con el tictac del reloj cuando no le presta atención. Pero el sonido misterioso se volvió más intenso y los obligó a prestar atención. Los muchachos se incorporaron, se miraron unos a otros, y luego adoptaron una actitud expectante. Reinó un largo silencio, profundo e ininterrumpido; después una detonación profunda y opaca llegó flotando desde la distancia."}, {"type": "p", "text": "—¿Qué es eso? —exclamó Joe sin voz apenas."}, {"type": "p", "text": "—¡Y yo qué sé! —dijo Tom en un susurro."}, {"type": "p", "text": "—Es un trueno —dijo Huckleberry en un tono asustado—, porque el trueno…"}, {"type": "p", "text": "—¡Atención! —dijo Tom—. Escuchad… no habléis."}, {"type": "p", "text": "Esperaron un rato que les pareció un siglo, y luego el mismo sordo fragor turbó la solemne quietud."}, {"type": "p", "text": "—Vamos a ver qué es."}, {"type": "p", "text": "Se levantaron de un salto y corrieron hacia la ribera más próxima al pueblo. Apartaron los matorrales de la orilla y atisbaron en dirección al agua. El pequeño barco de vapor estaba a una milla del pueblo, dejándose arrastrar por la corriente. Su ancha cubierta parecía repleta de gente. Había un gran número de botes llevados a remo o flotando con la corriente en las cercanías del vapor, pero los muchachos no pudieron determinar qué hacían los hombres que los ocupaban. Poco después un gran chorro de humo blanco surgió a un costado del vapor, y mientras se expandía y se levantaba en una perezosa nube, la misma detonación opaca llegó de nuevo a oídos de los muchachos."}, {"type": "p", "text": "—Ya lo sé —exclamó Tom—; alguien que se habrá ahogado."}, {"type": "p", "text": "—Es verdad —dijo Huck—; es lo que hicieron el verano pasado, cuando se ahogó Bill Turner; disparan cañonazos sobre el agua, y eso atrae el cuerpo a la superficie. Sí, y cogen hogazas de pan con azogue dentro y las echan al agua, y donde hay algún ahogado, allí va la hogaza y se para."}, {"type": "p", "text": "—Sí, he oído hablar de eso —dijo Joe—. No sé cómo el pan puede hacer una cosa así."}, {"type": "p", "text": "—No es el pan, ni mucho menos —dijo Tom—; calculo que será, sobre todo, lo que dicen sobre él cuando lo echan al agua."}, {"type": "p", "text": "—Pero si no dicen nada sobre él —dijo Huck—. Lo he visto y no dicen nada."}, {"type": "p", "text": "—Pues es muy curioso —dijo Tom—. Pero tal vez lo digan para sus adentros. Claro que sí. Eso lo sabe cualquiera."}, {"type": "p", "text": "Los otros estuvieron de acuerdo con lo que Tom decía, porque no se podía esperar que un ignorante pedazo de pan, sin ser instruido por un hechizo, obrase con mucha inteligencia al ser enviado en misión de tal gravedad."}, {"type": "p", "text": "—¡Diantre! Cómo me gustaría estar allí ahora —dijo Joe."}, {"type": "p", "text": "—Y a mí —dijo Huck—. Daría no sé qué por saber quién es."}, {"type": "p", "text": "Continuaron escuchando y observando. A Tom se le ocurrió un pensamiento revelador y exclamó:"}]$lira$::jsonb,
  711
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  41,
  'Los filibusteros acampan felizmente (3/3)',
  $lira$[{"type": "p", "text": "—Chicos, ya sé quién se ha ahogado: nosotros —exclamó."}, {"type": "p", "text": "Al instante se sintieron héroes; ¡qué triunfo tan esplendoroso! Los echaban de menos; los lloraban; había corazones destrozados por su causa; derramaban lágrimas; había conciencias en las que surgían recuerdos acusadores de crueldades con los pobres muchachos perdidos, que se entregaban a remordimientos vanos; y lo mejor de todo era que los desaparecidos eran motivo de charla en todo el pueblo; y la envidia de todos los muchachos en lo que se refiere a deslumbrante notoriedad. Era estupendo. A fin de cuentas, valía la pena ser pirata."}, {"type": "p", "text": "Al anochecer el vapor volvió a sus tareas acostumbradas, y los botes desaparecieron. Los piratas regresaron al campamento. La vanidad de su nueva grandeza y la insigne confusión que estaban causando los llenaba de júbilo. Pescaron algunos peces, los guisaron y comieron, y luego se pusieron a conjeturar qué pensaba y decía de ellos el pueblo; y los cuadros que imaginaban de la consternación pública motivada por ellos eran muy gratos de contemplar desde su punto de vista. Pero cuando los envolvieron las sombras de la noche, fueron dejando de hablar y se quedaron sentados con la mirada en el fuego y el pensamiento vagando por otra parte. La exaltación había desaparecido, y Tom y Joe no podían apartar el pensamiento de ciertas personas de su casa que no gozaban lo mismo que ellos en aquella travesura. Llegaron los recelos; poco a poco se sintieron turbados e infelices; exhalaron inadvertidamente un suspiro o dos. Al fin, Joe, con gran timidez, les tendió un disimulado anzuelo para ver cómo se tomarían los otros la idea de volver a la civilización, «no precisamente ahora, pero…»."}, {"type": "p", "text": "Tom lo avergonzó con sus escarnios. Huck, que no se había comprometido aún, se unió a Tom, y el irresoluto se retractó enseguida, considerándose dichoso de escapar del mal paso con tan poca fama de «gallina nostálgica» como le fue posible. Por el momento, la rebelión fue ahogada eficazmente. A medida que avanzaba la noche, Huck empezó a cabecear, y poco después a dormir. Joe lo siguió. Tom permaneció un rato inmóvil, apoyado sobre el codo, observando con detenimiento a sus compañeros. Por último se levantó con cautela sobre las rodillas y se puso a buscar entre la hierba al vacilante resplandor de la fogata. Recogió e inspeccionó varios anchos semicírculos de fina y blanca corteza de sicomoro, y al final eligió dos que le parecieron convenientes. Entonces se arrodilló junto al fuego y penosamente escribió algo sobre cada uno de los pedazos con su lápiz; enrolló uno de ellos y se lo puso en el bolsillo de la chaqueta, y el otro en el sombrero de Joe, que luego trasladó a corta distancia de su dueño. Puso también en el sombrero algunos tesoros de chico de escuela de valor casi incalculable, entre ellos un trozo de yeso, una pelota de caucho, tres anzuelos y una canica de las llamadas de «cristal irrompible». Se alejó de puntillas entre los árboles hasta comprender que no podían oírlo, y emprendió una veloz carrera en dirección al banco de arena."}]$lira$::jsonb,
  516
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  42,
  'Tom hace una furtiva visita a su hogar (1/2)',
  $lira$[{"type": "p", "text": "Unos minutos más tarde Tom se encontraba en el agua poco profunda del banco de arena, vadeando hacia la ribera del Illinois. Antes de que el agua le llegase a la cintura había recorrido la mitad del camino; luego la corriente ya no le permitió seguir vadeando, así que se puso a nadar sin temor para recorrer las cien yardas restantes. Nadaba sesgando la corriente, pero, aun así, era arrastrado hacia abajo más deprisa de lo que esperaba. Al final logró alcanzar la orilla y la siguió hasta encontrar un sitio bajo para salir del agua. Se puso la mano en el bolsillo de la chaqueta, halló intacto el trozo de corteza, y entonces emprendió la marcha a través del bosque, siguiendo la playa, con la ropa chorreando. Poco antes de las diez llegó a un lugar despejado frente al pueblo, y vio el vapor amarrado en la ribera, a la sombra de los árboles. Todo era quietud bajo el parpadeo de las estrellas. Se deslizó hasta la orilla, con sumo cuidado, se metió en el agua, dio tres o cuatro brazadas y se encaramó en el bote que hacía de chinchorro a la popa del barco. Se tendió bajo el banco de los remeros y esperó jadeante."}, {"type": "p", "text": "No tardó en sonar la agrietada campana y una voz dio la orden de «arrancar». Unos minutos más tarde la proa del bote se erguía contra el vientre del vapor, y el viaje había comenzado. Tom se alegró de su éxito, pues sabía que era el último trayecto nocturno del vapor. Al cabo de un cuarto de hora interminable las ruedas se detuvieron, y Tom se deslizó por la borda y nadó hacia la orilla a oscuras, alcanzando la tierra cincuenta yardas más abajo, fuera del peligro de posibles indiscretos."}, {"type": "p", "text": "Recorrió calles poco frecuentadas y al poco rato se encontró frente a la valla posterior de la casa de su tía. Saltó por encima de ella, se acercó al desván y miró al interior de la casa por la ventana del salón, que estaba iluminada. La tía Polly, Sid, Mary y la madre de Joe Harper estaban sentados en grupo, hablando. Estaban cerca de la cama, que se hallaba entre ellos y la puerta. Tom se dirigió a la puerta y comenzó a levantar suavemente el pestillo; luego empujó la puerta, que hizo un chirrido; continuó empujando con cautela, temblando cada vez que chirriaba, hasta que juzgó que podría escurrirse por la abertura de rodillas; entonces metió la cabeza y comenzó a entrar con prudencia."}, {"type": "p", "text": "—¿Por qué oscila tanto la llama de la vela? —dijo la tía Polly. Tom se apresuró—. Pero ¡si la puerta está abierta! Pues claro que lo está. Aquí no paran de ocurrir hechos extraños. Ciérrala, Sid. Tom desapareció bajo la cama justo a tiempo. Se quedó tumbado un rato «recuperando el aliento», y luego se arrastró hacia un lugar desde donde casi podía tocar el pie de su tía."}, {"type": "p", "text": "—Como decía —continuó la tía Polly—, no era malo, lo que se dice malo, sino travieso. Un poco imprudente y atolondrado, ¿sabe usted? No tenía más responsabilidad que un potrillo. Nunca mostró malas intenciones, y era el chico con el corazón más bueno que haya existido nunca —concluyó echándose a llorar."}, {"type": "p", "text": "—Lo mismo le digo de mi Joe; siempre lleno de proyectos endiablados y dispuesto a cualquier travesura, pero tan generoso y bueno como se pueda ser, y, Dios me bendiga, ¡pensar que lo zurré por comerse aquella crema, sin acordarme de que yo misma la había tirado porque estaba agria! Nunca volveré a verlo en este mundo, nunca, nunca, nunca, ¡pobre hijo mío!"}, {"type": "p", "text": "La señora Harper empezó a sollozar como si se le partiera el corazón."}, {"type": "p", "text": "—Espero que Tom se encuentre bien allí donde esté —dijo Sid—, pero si se hubiera portado mejor… —¡Sid! —Tom sintió el fulgor de la mirada de la anciana, aunque no podía verla—. Ni una palabra contra mi Tom, ahora que se ha ido. Dios cuidará de él; no tienes por qué preocuparte. ¡Ay, señora Harper, no sé cómo resignarme! ¡No sé cómo resignarme! ¡Era un consuelo tan grande para mí, aunque atormentase mi viejo corazón con tanta frecuencia!"}, {"type": "p", "text": "—El Señor nos lo da, y el Señor nos lo quita; ¡bendito sea el nombre del Señor! Pero ¡es muy duro! ¡Cuando pienso que el pasado sábado mi Joe me lanzó un cohete a la nariz, y lo zurré de lo lindo! Poco sabía yo cuán pronto… Si me lo hiciera otra vez, lo abrazaría y lo bendeciría."}, {"type": "p", "text": "—Comprendo sus sentimientos, señora Harper, comprendo perfectamente sus sentimientos. Ayer por la tarde, sin ir más lejos, mi Tom hizo tragar al gato el contenido del frasco del «bálsamo milagroso», y creí que el animalito iba a destrozar la casa. Y Dios me perdone, le di a Tom en la cabeza con mi dedal, pobrecillo… Ahora ya han concluido todos sus pesares. Y las últimas palabras que le oí decir eran de reproche…"}, {"type": "p", "text": "Ese recuerdo era excesivo para la anciana, que rompió en desconsolados sollozos. Tom estaba lloriqueando también, y sentía más compasión por sí mismo que nadie. Oía a Mary llorando y diciendo palabras amables en su memoria de vez en cuando. Empezaba a tener una opinión nobilísima de sí mismo. Con todo, estaba tan enternecido por el dolor de su tía que anhelaba salir de debajo la cama y llenarla de alegría; y la deslumbrante teatralidad de la escena le atraía poderosamente, pero se contuvo y continuó inmóvil."}]$lira$::jsonb,
  915
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  43,
  'Tom hace una furtiva visita a su hogar (2/2)',
  $lira$[{"type": "p", "text": "Siguió escuchando e intuyó que al principio se creyó que los muchachos se habían ahogado bañándose; luego echaron en falta la balsa; después algunos chicos dijeron que los desaparecidos habían prometido que el pueblo pronto «sabría algo»; los sabihondos del lugar «ataron los cabos sueltos» y dedujeron que los muchachos habían huido en la balsa y aparecerían en breve en el pueblo vecino, río abajo; pero a mediodía encontraron la balsa empotrada contra la orilla del Missouri, unas cinco o seis millas más abajo del pueblo, y entonces murieron las esperanzas; debían de haberse ahogado, pues de lo contrario el hambre los hubiera hecho volver a casa al anochecer, si no antes. Se creía que la busca de los cuerpos había sido infructuosa, porque la desgracia debió de ocurrir en mitad de la corriente, ya que de otro modo, siendo los chicos buenos nadadores, habrían logrado alcanzar la orilla. Eso ocurrió la noche del miércoles. Si los cuerpos no se hallaban en lo que quedaba de semana se abandonaría toda esperanza, y los funerales se celebrarían la mañana del domingo. Tom se estremeció."}, {"type": "p", "text": "La señora Harper dio las buenas noches sollozando y se dispuso a partir. Entonces, en un impulso mutuo, las dos desoladas mujeres se arrojaron una en brazos de la otra, deshaciéndose en un llanto que las consolaba, y luego se separaron. La tía Polly mostró una ternura desacostumbrada al desear las buenas noches a Sid y a Mary. Sid gimoteó un poco, y Mary salió llorando a lágrima viva. La tía Polly se arrodilló y rezó por Tom con tanto patetismo, tanto fervor y tanto amor desmedido en sus palabras y en su vieja voz temblorosa que el muchacho volvió a deshacerse en lágrimas mucho antes de que terminarse la plegaria."}, {"type": "p", "text": "Se vio obligado a permanecer inmóvil hasta mucho después que se acostara la tía Polly, porque esta siguió lanzando suspiros y lastimeras quejas a intervalos, mientras se removía inquieta y daba vueltas. Al final se sosegó, gimiendo un poco en sueños. Entonces el muchacho se deslizó fuera de la cama, se levantó poco a poco hasta ponerse en pie, cubrió con la mano la luz de la vela, y se quedó contemplando a la tía Polly. Su corazón rebosaba de piedad hacia ella. Sacó el rollo de sicomoro y lo depositó junto a la vela. Pero entonces se le ocurrió una idea y estuvo un rato cavilando. El rostro se le iluminó al hallar una feliz solución a su pensamiento; se guardó la corteza a toda prisa en el bolsillo. Entonces se inclinó sobre la tía Polly y besó sus labios marchitos, y, sin entretenerse más, salió a escondidas de la sala, cerrando la puerta. Hizo el camino de regreso al embarcadero, no encontró a nadie por los alrededores y subió a bordo sin temor, pues sabía que la embarcación estaba vacía, a excepción de un vigilante que siempre estaba dentro y dormía como un leño. Desamarró el bote de la popa, se metió en él, y pronto estuvo remando con cautela río arriba. Cuando estuvo a una milla del pueblo, empezó a sesgar la corriente, poniendo todo su empeño en la tarea. Alcanzó exactamente el embarcadero de la otra orilla, pues tal operación le resultaba familiar. Sintió el deseo de capturar el bote, arguyendo que podía ser considerado un buque y una presa legítima, por tanto, para un pirata, pero sabía que lo buscarían minuciosamente y que podría conducir a ciertas revelaciones. En consecuencia, saltó a tierra y se adentró en el bosque."}, {"type": "p", "text": "Se sentó y descansó un buen rato, tratando de mantenerse despierto, y entonces emprendió el fatigoso camino hacia el campamento. La noche tocaba a su fin. Ya era de día antes de que se hallase ante el banco de arena de la isla. Descansó hasta que el sol estuvo bien alto y doró el ancho río con su esplendor, y entonces se zambulló en la corriente. Poco después se detenía, goteando, en el umbral del campamento, y oía decir a Joe:"}, {"type": "p", "text": "—No. Tom es un hombre de honor, Huck, y volverá. No será un desertor. Sabe que sería una mancha para un pirata, y Tom es demasiado orgulloso para consentirlo. Tendrá algo que hacer. Ya quisiera yo saber qué."}, {"type": "p", "text": "—Bien, ¿así todas las cosas son nuestras ahora?"}, {"type": "p", "text": "—Casi, casi, pero todavía no, Huck. La nota dice que lo serán si no está aquí a la hora del desayuno."}, {"type": "p", "text": "—¡Y aquí está! —exclamó Tom con gran efecto dramático, haciendo una majestuosa irrupción en el campamento."}, {"type": "p", "text": "Prepararon enseguida un sabroso desayuno de beicon y pescado, y mientras los muchachos daban buena cuenta de él, Tom contó (y adornó) sus aventuras. Cuando terminó la historia, se habían convertido en un jactancioso terceto de héroes. Luego Tom se escondió en un rincón a la sombra para dormir hasta mediodía, y los otros dos piratas se prepararon para ir de pesca y de exploración."}]$lira$::jsonb,
  817
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  44,
  'El placer de fumar – «he perdido el cuchillo» (1/4)',
  $lira$[{"type": "p", "text": "Después de comer toda la banda salió a la caza de huevos de tortuga en el banco de arena. Fueron de un lado a otro clavando palitos en la arena, y cuando encontraban un lugar blando, se arrodillaban y cavaban con las manos. A veces en un solo agujero encontraban cincuenta o sesenta huevos. Eran perfectamente blancos y redondos, un poco más pequeños que una nuez inglesa. Aquella noche hicieron un banquete de huevos fritos, y la mañana del viernes otro."}, {"type": "p", "text": "Después de desayunar fueron gritando y corriendo hacia el banco de arena, dando vueltas y quitándose la ropa mientras corrían, hasta que estuvieron desnudos, y continuaron la diversión en el agua del banco, contra la fuerte corriente, que les echaba la zancadilla de vez en cuando y aumentaba en gran manera el placer del juego. A veces se agachaban en grupo y chapoteaban en el agua salpicándose los rostros, y se aproximaban despacio unos a otros, con la cabeza vuelta para evitar la rociada de salpicones, y al final se agarraban y se peleaban hasta que el más fuerte chapuzaba a su vecino, y entonces se hundían todos en una mezcolanza de piernas y brazos blancos, boqueando en busca de aliento."}, {"type": "p", "text": "Si la fatiga los vencía, salían del agua y se echaban sobre la arena cálida y seca, y allí yacían y se cubrían con ella, y al poco rato se zambullían en el agua otra vez y reanudaban el juego. Al final se les ocurrió que su piel desnuda se parecía bastante al traje de malla de los payasos; de modo que trazaron una circunferencia en la arena y jugaron al circo, con tres payasos dentro, pues ninguno quiso ceder aquel honrosísimo papel a sus compañeros."}, {"type": "p", "text": "Más tarde sacaron las canicas y jugaron hasta que se cansaron de esa diversión. Entonces Joe y Huck se bañaron otra vez, pero Tom no quiso arriesgarse, porque descubrió que al sacarse los pantalones había perdido la ristra de cascabeles de serpiente que llevaba alrededor del tobillo, y se maravillaba de que hubiese escapado a los calambres tanto tiempo, sin la protección de aquel poderoso amuleto. No quiso aventurarse hasta que lo hubo encontrado, pero entonces los otros ya estaban fatigados y tenían ganas de descansar. Poco a poco se separaron unos de otros, vagando a solas, llenos de melancolía, y comenzaron a dirigir anhelantes miradas a través del ancho río, hacia donde el pueblo yacía perezosamente al sol. Tom se dio cuenta de que estaba escribiendo Becky en la arena con el dedo gordo del pie; lo borró y se enojó consigo mismo por su debilidad. Sin embargo, lo escribió de nuevo; no podía evitarlo. Volvió a borrarlo, y se puso a salvo de la tentación, llamando a los demás muchachos y uniéndose a ellos. Los ánimos de Joe estaban tan decaídos que casi no admitían resurrección. Sentía tanta añoranza que apenas podía soportar el abatimiento que le causaba. Estaban a punto de saltársele las lágrimas. Huck también estaba melancólico. Tom se sentía abatido, pero trataba con todas sus fuerzas de disimularlo. Tenía un secreto que aún no estaba dispuesto a descubrir, pero si la desmoralización no cesaba pronto, tendría que revelarlo. Con grandes muestras de alegría, exclamó:"}, {"type": "p", "text": "—Apuesto a que en esta isla ya hubo piratas alguna vez. Tenemos que volver a explorarla. Debe de haber tesoros escondidos en algún sitio. ¿Qué os parecería encontrar un viejo arcón repleto de oro y plata? Pero tan solo despertó un débil entusiasmo, que se extinguió sin ninguna respuesta. Tom probó una o dos seducciones más, pero fracasaron también. Era una tarea desalentadora. Joe estaba sentado hurgando en la arena con un palo con el semblante muy triste."}, {"type": "p", "text": "—Bueno, chicos, dejémoslo. Quiero volver a casa. Aquí es tan solitario… —dijo al fin."}, {"type": "p", "text": "—No, Joe, te pasará enseguida —dijo Tom—. Acuérdate de lo bien que pescamos aquí."}, {"type": "p", "text": "—¡Qué me importa a mí la pesca! Quiero volver a casa."}, {"type": "p", "text": "—Pero, Joe, ¡si no encontraremos otro sitio mejor que este para nadar!"}, {"type": "p", "text": "—Me da igual. Me estoy dando cuenta de que me da igual bañarme si nadie me lo prohíbe. Estoy decidido a marcharme a casa."}, {"type": "p", "text": "—¡Bah, qué niño de teta! ¿Es que necesitas ver a tu madre?"}, {"type": "p", "text": "—Sí, necesito ver a mi madre, y a ti te ocurriría lo mismo, si tuvieras. No soy más niño de teta que tú. Joe gimoteó un poco."}, {"type": "p", "text": "—Bien, dejaremos que el niño llorón vaya a su casa con mamita, ¿verdad, Huck? ¡Pobrecillo! Necesita ver a su mamá. Bien, que la vea. Tú estás bien aquí, ¿verdad, Huck? Nosotros nos quedaremos, ¿eh, Huck? Huck dijo sí sin el menor entusiasmo."}, {"type": "p", "text": "—No volveré a dirigirte la palabra mientras viva —dijo Joe levantándose—. ¡Jamás!"}, {"type": "p", "text": "Se alejó enfurruñado y comenzó a vestirse."}]$lira$::jsonb,
  790
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  45,
  'El placer de fumar – «he perdido el cuchillo» (2/4)',
  $lira$[{"type": "p", "text": "—¿Y a quién le importa? —dijo Tom—. No me moriré por eso. Vete a casa para que se rían de ti. ¡Qué pirata! Huck y yo no somos niños llorones. Nos quedaremos, ¿verdad, Huck? Que se vaya, si quiere. Supongo que nos las arreglaremos sin él."}, {"type": "p", "text": "A pesar de sus palabras de desprecio, Tom estaba inquieto y se alarmó al ver que Joe continuaba vistiéndose sombríamente. Y era desagradable ver a Huck contemplando tan pensativo los preparativos de Joe, y guardando aquel silencio de mal agüero. Al cabo de poco, sin una palabra de despedida, Joe empezó a vadear en dirección a la ribera del Illinois. El valor de Tom empezó a flaquear. Miró a Huck. Este no pudo resistir la mirada, y bajó los ojos."}, {"type": "p", "text": "—Yo también quiero irme, Tom. Esto ya era muy solitario, y ahora será peor. Vámonos también, Tom —dijo."}, {"type": "p", "text": "—Yo no. Podéis marcharos, si queréis. Yo pienso quedarme."}, {"type": "p", "text": "—Tom, yo prefiero irme."}, {"type": "p", "text": "—Bien, vete, ¿quién te lo impide?"}, {"type": "p", "text": "Huck empezó a recoger sus ropas desparramadas y dijo:"}, {"type": "p", "text": "—Tom, me gustaría que vinieras con nosotros. Anda, decídete. Te esperaremos al llegar a la orilla."}, {"type": "p", "text": "—Pues os cansaréis esperándome, eso es todo."}, {"type": "p", "text": "Huck emprendió tristemente la marcha, y Tom lo vio alejarse, mientras le atenazaba el corazón el poderoso deseo de abandonar su orgullo y marcharse con ellos. Tenía la esperanza de que los muchachos se pararían, pero ellos seguían vadeando despacio. De pronto Tom se dio cuenta de la soledad y la quietud que lo rodeaban. Luchó una última vez con su orgullo y luego se precipitó en pos de sus camaradas gritando:"}, {"type": "p", "text": "—¡Esperad! ¡Esperad! Tengo que deciros algo."}, {"type": "p", "text": "Joe y Huck se detuvieron. Cuando Tom llegó junto a ellos, comenzó a revelarles su secreto, y ellos escucharon malhumorados hasta que al final vieron el «punto» al que se dirigía, y entonces lanzaron un bélico alarido de aplauso y dijeron que era «espléndido» y que si lo hubiese dicho al principio, no se habrían marchado. Tom dio una excusa cualquiera; pero el verdadero motivo era el temor de que ni siquiera el secreto los mantuviera a su lado mucho tiempo, de modo que había decidido reservarlo como una postrera seducción."}, {"type": "p", "text": "Los muchachos regresaron alegremente y reanudaron con decisión sus diversiones, charlando sin cesar del magnífico proyecto de Tom y admirando su talento. Después de una comida exquisita de huevos y pescado, Tom dijo que deseaba aprender a fumar. Joe se sumó a la idea y dijo que a él también le gustaría probarlo. Así, pues, Huck hizo unas pipas y las llenó. Aquellos bisoños jamás habían fumado otra cosa que cigarros hechos de hojas secas, que picaban en la lengua y no se consideraban muy de hombres. Se tendieron apoyándose sobre el codo y comenzaron a echar bocanadas con escasa confianza. El humo tenía un sabor desagradable que les daba náuseas, pero Tom dijo:"}, {"type": "p", "text": "—Pero ¡si es muy fácil! Si hubiera sabido que esto era todo, hace tiempo que habría aprendido."}, {"type": "p", "text": "—Y yo —dijo Joe—. Eso no es nada."}, {"type": "p", "text": "—Muchas veces he observado a la gente que fuma, diciéndome que me gustaría hacerlo; pero nunca había creído que pudiese —dijo Tom."}, {"type": "p", "text": "—Es exactamente lo que me ocurría a mí, ¿verdad, Huck? Tú ya me habías oído, ¿no, Huck? Que diga Huck si no es cierto."}, {"type": "p", "text": "—Sí, lo habías dicho muchas veces —dijo Huck."}, {"type": "p", "text": "—También yo —dijo Tom—; ¡centenares de veces! Una vez en el matadero. ¿No te acuerdas, Huck? Bob Tanner también estaba allí, y Johnny Miller, y Jeff Thatcher, cuando lo dije. ¿Recuerdas, Huck, que lo dije?"}, {"type": "p", "text": "—Sí, es verdad —dijo Huck—. Fue un día después de perder yo la canica blanca. No, fue el día antes."}, {"type": "p", "text": "—¿Lo ves? Ya te lo decía —exclamó Tom—. Huck se acuerda."}, {"type": "p", "text": "—Creo que podría fumar esta pipa durante un día entero —dijo Joe—. No me mareo."}, {"type": "p", "text": "—Ni yo —dijo Tom—. Yo fumaría durante todo el día. Pero apuesto a que Jeff Thatcher no podría."}, {"type": "p", "text": "—¡Jeff Thatcher! A las dos chupadas se quedaría listo. ¡Que lo pruebe un día y verá!"}, {"type": "p", "text": "—Seguro. Y Johnny Miller igual; quisiera ver a Johnny Miller intentarlo algún día."}, {"type": "p", "text": "—¡Y yo! —dijo Joe—. Bueno, te apuesto a que Johnny Miller no podría ni empezar. Solo con el olor se marearía."}, {"type": "p", "text": "—Seguro, Joe. Oye, me gustaría que nos viesen los chicos ahora."}, {"type": "p", "text": "—A mí también."}, {"type": "p", "text": "—Escuchad, muchachos, y no digáis nada de esto; algún día que todos estén por allí, te diré, «Joe, ¿tienes una pipa? Me gustaría fumar». Y tú, con indiferencia, como una cosa corriente, dirás: «Sí, tengo mi vieja pipa, y otra, pero mi tabaco no es muy bueno». Y yo diré: «Ya está bien, si es fuerte». Y entonces tú sacarás las pipas, y las encenderemos como si tal cosa, y ya verás la cara de asombro que ponen."}]$lira$::jsonb,
  798
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  46,
  'El placer de fumar – «he perdido el cuchillo» (3/4)',
  $lira$[{"type": "p", "text": "—¡Córcholis, Tom, será estupendo! ¡Ojalá fuese ahora!"}, {"type": "p", "text": "—¡Ojalá! Y cuando les digamos que aprendimos siendo piratas, ¿no desearán haber estado aquí?"}, {"type": "p", "text": "—Desde luego. ¡Imagina si lo desearán!"}, {"type": "p", "text": "Continuaron charlando. Pero a poco la conversación comenzó a decaer y a desarticularse. Los silencios se alargaron; las expectoraciones aumentaron maravillosamente. Cada poro interior de las mejillas de los chicos se convirtió en una fuente borbotante; apenas pudieron cerrar a tiempo la bodega que tenían bajo la lengua para impedir una inundación; a pesar de sus esfuerzos, se sucedían pequeños desbordamientos en la garganta, seguidos cada vez de repentinas náuseas. Los dos muchachos estaban muy pálidos y abatidos. La pipa de Joe le resbaló de los dedos inertes. A Tom también se le cayó. Las dos fuentes manaban con furia y las dos bombas funcionaban a toda marcha para extraer el agua."}, {"type": "p", "text": "—He perdido el cuchillo. Creo que será mejor que vaya a buscarlo —dijo Joe sin fuerzas. Tom, con los labios temblorosos y una pronunciación pausada, dijo:"}, {"type": "p", "text": "—Será mejor que te ayude. Tú puedes ir por aquel lado y yo buscaré alrededor del manantial. No, no hace falta que vengas, Huck, ya lo encontraremos."}, {"type": "p", "text": "Huck volvió a sentarse, pues, y esperó durante una hora. Entonces lo encontró todo muy solitario, y fue a buscar a sus camaradas. Los encontró en el bosque, muy alejados el uno del otro, muy pálidos los dos y dormidos como troncos. Pero se dijo que si habían sentido alguna molestia, ya se habían desembarazado de ella."}, {"type": "p", "text": "Por la noche, a la hora de cenar, no estuvieron muy parlanchines. Mostraban una actitud humilde, y cuando Huck preparó su pipa después del ágape y se dispuso a prepararles las suyas, dijeron que no, que no se sentían muy bien, que algo que habían comido a mediodía les había sentado mal. A medianoche Joe se despertó y llamó a los otros. En el aire había una hosca opresión que parecía augurar algo malo. Los muchachos se juntaron y buscaron la compañía amistosa del fuego, pese a que el calor opaco y quieto de la atmósfera irrespirable fuese sofocante. Permanecían sentados, inmóviles y en actitud expectante. La solemne quietud continuaba. Más allá de la luz del fuego las tinieblas lo engullían todo. Al cabo de poco se produjo un tembloroso fulgor que iluminó vagamente el follaje durante un instante y luego se desvaneció. Después se produjo otro, un poco más fuerte. Más tarde otro. Entonces una débil queja suspiró a través de las ramas del bosque y los muchachos sintieron un hálito veloz en las mejillas y se estremecieron al pensar que el Espíritu de la Noche acababa de pasar por allí. Hubo una pausa. Entonces un relámpago siniestro convirtió la noche en día y mostró cada minúsculo tallo de hierba, separado y distinto, que crecía en torno a sus pies. Y mostró también tres caras asustadas y pálidas. El estruendo de un trueno se desplomó desde los cielos y se perdió en la distancia, entre opacos mugidos. Una ráfaga de aire frío arrancó murmullos a todas las hojas y desencadenó una nevada de copos de ceniza alrededor del fuego. Otro fiero resplandor iluminó el bosque, seguido por un estallido que pareció desgajar las copas de los árboles sobre la cabeza de los muchachos. Se apretujaron unos contra otros aterrorizados en medio de las espesas tinieblas que reinaron a continuación. Densos goterones comenzaron a tamborilear sobre el follaje."}, {"type": "p", "text": "—¡Deprisa, muchachos! Vamos a la tienda —exclamó Tom."}, {"type": "p", "text": "Tropezando con las raíces y las plantas, echaron a correr a toda prisa por la oscuridad, cada uno por su lado. Un viento furioso mugía entre los árboles, arrancando silbidos a su paso. Se sucedían sin tregua relámpagos cegadores, acompañados del estruendo ensordecedor del trueno. Caía un fuerte aguacero, que el huracán desparramaba por el suelo en espesas cortinas de agua. Los muchachos se llamaban a gritos, pero el bramido del viento y el retumbar de los truenos ahogaban por completo sus voces. Al final, uno tras otro llegaron bajo la tienda, ateridos, asustados y chorreando agua; pero les consolaba el hecho de estar unidos en el infortunio. No podían hablar, aunque los demás ruidos se lo hubieran permitido, a causa de la vieja vela que se agitaba con furia. La tempestad se intensificaba gradualmente, y al cabo de poco la vela rompió sus ligaduras y huyó entre aleteos, arrastrada por una ráfaga. Los muchachos se agarraron de las manos y emprendieron una carrera, con muchos tumbos y magulladuras, en busca de la protección de un gran roble que se alzaba en la ribera. La batalla estaba en su punto culminante. Bajo la incesante conflagración de los relámpagos que llameaban en las alturas, las cosas de la tierra se destacaban con agudos perfiles sin sombra: los árboles encorvados, el río agitado e hirviente de espuma, las rociaduras de lechosos salpicones, la silueta opaca de los altos acantilados en la orilla opuesta, columbrados a través de las nubes huidizas y de la oblicua cortina de lluvia. Con frecuencia algún árbol gigante sucumbía a la lucha, y se desplomaba ruidosamente entre la vegetación más joven; y el trueno incansable llegaba en explosiones que destrozaban los oídos, agudas y penetrantes, inexplicablemente aterradoras. La tormenta culminó en un esfuerzo incomparable que pareció despedazar la isla, abrasarla y ahogarla hasta la cima de los árboles, llevársela en un soplo, y ensordecer toda cosa viva que hubiese en ella. Era una mala noche para unos muchachos sin techo."}]$lira$::jsonb,
  907
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  47,
  'El placer de fumar – «he perdido el cuchillo» (4/4)',
  $lira$[{"type": "p", "text": "Pero al fin concluyó la batalla; las fuerzas se retiraron entre amenazas y gruñidos cada vez más débiles, y la paz recobró su autoridad. Los muchachos volvieron al campamento empavorecidos, pero allí encontraron algo que les hizo sentir gratitud, pues el gran sicomoro, abrigo de sus lechos, estaba en ruinas, fulminado por los rayos, y ellos no se hallaban bajo su copa al suceder la catástrofe. El campamento estaba empapado de agua, incluida la fogata. Eran unos rapaces atolondrados, cosa propia de su generación, y no habían tomado precauciones contra la lluvia. Tenían motivos para lamentarse, pues estaban ateridos de frío y calados hasta los huesos. Fueron elocuentes en su desastre; pero enseguida descubrieron que el fuego se había adentrado tanto bajo el tronco que le servía de protección (en el sitio donde se erguía y se separaba del suelo) que un palmo, o algo así, de terreno había escapado al remojón. Lucharon pacientemente hasta que, con ramitas y cortezas que recogieron en los costados de los troncos protegidos, lograron que la fogata ardiera de nuevo. Entonces amontonaron grandes ramas muertas hasta que tuvieron un horno que crepitaba devolviéndoles el optimismo perdido. Secaron el jamón hervido y celebraron un festín, y después se sentaron junto al fuego y exageraron y glorificaron su aventura de medianoche hasta que apuntó el día, pues en parte había espacio seco donde dormir."}, {"type": "p", "text": "En cuanto el sol volvió a calentar a los muchachos, los invadió el sueño y se encaminaron hacia el banco de arena para tumbarse a dormir. Al poco rato se les empezó a chamuscar la piel y, abatidos, se dispusieron a preparar el desayuno. Después de comer se sintieron entorpecidos, con las articulaciones embotadas y, una vez más, llenos de añoranza. Tom vio los síntomas y empezó a animar a los piratas tan bien como pudo. Pero ya no les importaba nada: ni las canicas, ni el circo, ni los baños. Les recordó el imponente secreto y despertó un rayo de optimismo. Mientras duró, logró interesarlos en un nuevo invento. Consistía en dejar de ser piratas durante un rato para convertirse en indios. Los atrajo la idea y al poco rato estaban desnudos y pintarrajeados de pies a cabeza con barro negro, como cebras —todos eran jefes de tribu, por supuesto—, y entonces se adentraron bélicamente en los bosques para atacar un poblado inglés."}, {"type": "p", "text": "Luego se separaron y se convirtieron en tribus hostiles, se tendieron emboscadas y se atacaron dando pavorosos aullidos de guerra, y se mataron y se arrancaron la cabellera los unos a los otros millares de veces. Fue un día sangriento. Y, por tanto, extraordinariamente divertido."}, {"type": "p", "text": "Se reunieron a la hora de cenar en el campamento, hambrientos y felices; pero entonces surgió una dificultad: los indios hostiles no podían romper juntos el pan de la hospitalidad sin hacer antes las paces, lo cual era sencillamente imposible sin fumar la pipa de la paz. Jamás habían oído que existiera otro procedimiento. Dos de los salvajes, por lo menos, casi desearon haber continuado siendo piratas. Sin embargo, no quedaba otro remedio; con todas las posibles demostraciones de contento, pidieron la pipa y echaron su bocanada de humo a conciencia cuando les llegó el turno."}, {"type": "p", "text": "Lo curioso es que entonces se alegraron de haberse dedicado al salvajismo, pues habían conseguido algo; vieron que podían fumar un poco sin tener que ir en busca de cuchillos perdidos; no se marearon lo suficiente como para sentirse indispuestos. No era fácil que renunciaran a esa promesa por falta de esfuerzo. No: hicieron cautelosas prácticas después de cenar con enorme éxito, de modo que pasaron una jubilosa velada. Estaban más orgullosos y contentos con su nueva adquisición que si hubiesen escalpado y despellejado a las Seis Naciones. Vamos a dejarles que fumen y se pavoneen, puesto que de momento ya no nos son de ninguna utilidad."}]$lira$::jsonb,
  640
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  48,
  'Los piratas asisten a sus propios funerales (1/2)',
  $lira$[{"type": "p", "text": "Pero aquella apacible tarde de sábado no había risas en el pueblecillo. Los Harper y la familia de la tía Polly se estaban vistiendo de luto con gran dolor y muchas lágrimas. En el pueblo reinaba una calma desacostumbrada, aunque de ordinario fuese muy tranquilo. La gente se ocupaba de sus tareas con aire ausente; hablaba poco, pero suspiraba con frecuencia. A los niños les parecía una carga que el sábado fuera fiesta. No ponían el alma en las diversiones, sino que enseguida las abandonaban. Aquella tarde Becky Thatcher estuvo rondando muy abatida el desierto patio de la escuela, presa de una honda melancolía. Pero no encontró nada que la consolase. Sostenía este soliloquio:"}, {"type": "p", "text": "—Si al menos tuviera otra vez aquella manecilla de latón… Pero no poseo ningún recuerdo suyo. — Ahogó un ligero sollozo, se detuvo y dijo para sí—: Fue aquí mismo. Si ocurriera otra vez, no diría aquellas palabras, no las diría por nada del mundo. Pero ya no es posible; jamás, jamás, jamás le volveré a ver."}, {"type": "p", "text": "Tal pensamiento acabó de desazonarla y se alejó sin rumbo, con las lágrimas resbalándole por las mejillas. Entonces llegó un nutrido grupo de chicos y chicas —compañeros de juego de Tom y de Joe—, y se quedaron mirando por encima de la empalizada y hablando con reverencia de cómo Tom hacía eso y aquello, de la última vez que lo vieron, y de cómo dijo Joe tales o cuales cosas (¡frases henchidas de pavorosos augurios, como acababan de descubrir!), y cada uno que hablaba indicaba el lugar exacto donde estaban los muchachos perdidos en aquel entonces y añadían algo así: «Y yo estaba precisamente aquí, donde estoy ahora, y como si tú fueses él… estaba así de cerca y él sonrió de esta manera… y entonces sentí algo, como… ¡horrible!, ¿sabéis?, y nunca pensé en lo que podría significar, por supuesto, pero ¡ahora se ve bien claro!»."}, {"type": "p", "text": "Surgió entonces una disputa sobre quién vio vivos por última vez a los muchachos muertos, y muchos reclamaron aquella tétrica distinción, y ofrecieron pruebas, más o menos confirmadas por los testigos; y cuando al final se decidió quiénes habían visto por última vez a los desaparecidos, y habían hablado con ellos por última vez, los afortunados revistieron una especie de importancia sagrada, y fueron objeto de envidia por parte de todos los demás. Un pobre rapaz, que no tenía otra grandeza que ofrecer, dijo con bastante orgullo:"}, {"type": "p", "text": "—Una vez Tom Sawyer me dio una paliza."}, {"type": "p", "text": "Pero esta reivindicación de gloria fue un fracaso. La mayoría de los chicos podían decir otro tanto, de modo que abarataron demasiado la distinción. El grupo se alejó poco a poco, mientras seguía evocando recuerdos de los héroes desaparecidos con voces atemorizadas."}, {"type": "p", "text": "A la mañana siguiente, una vez concluida la escuela dominical, la campana comenzó a tocar a muertos, en lugar de tañer de la forma acostumbrada. Era un día muy apacible, y el funerario sonido parecía armonizar con el meditabundo silencio que se extendía sobre la naturaleza. La gente del pueblo empezó a reunirse, deteniéndose un instante en el vestíbulo para conversar en voz baja sobre el triste acontecimiento. Pero en la iglesia no se oía ni un solo murmullo; solo turbaba el silencio el tétrico susurro de la ropa de las mujeres al dirigirse a su sitio. Nadie recordaba haber visto nunca la iglesia tan llena. Al final hubo una pausa, un expectante silencio, y entonces entró la tía Polly con Sid y Mary, seguidos de la familia Harper, todos vistiendo de riguroso luto, y todos los fieles, incluido el viejo ministro, se alzaron reverentemente y se quedaron en pie, hasta que los enlutados se sentaron en el primer banco. Luego se hizo otro silencio general, interrumpido a intervalos por ahogados sollozos, y el pastor extendió las manos y rezó. Cantaron un himno conmovedor, y el texto que siguió fue: «Yo soy la resurrección y la vida». En el transcurso del servicio el clérigo hizo tales descripciones de las gracias, las maneras seductoras y las cualidades de los muchachos desaparecidos que todos los presentes, creyendo reconocerlas, sintieron un hondo pesar al recordar que siempre se habían mostrado ciegos a tales gracias, y que con la misma persistencia solo habían visto faltas y defectos en los pobres muchachos. El pastor relató también anécdotas conmovedoras de la vida de los desaparecidos, con el propósito de ilustrar sus naturalezas dulces y generosas, y la gente comprendió enseguida cuán nobles y hermosos eran tales episodios, mientras recordaban con dolor que en la época en que ocurrieron les habían parecido meras bribonadas, más bien merecedoras del látigo. La congregación, cada vez más conmovida a medida que proseguía la patética historia, al final dio rienda suelta a su emoción y se unió a los llorosos enlutados en un coro de angustiados sollozos, y hasta el predicador sucumbió a sus sentimientos y lloró en el púlpito. En la galería se oyó un chasquido en el que nadie reparó; un momento después la puerta de la iglesia chirrió; el ministro levantó sus anegados ojos del pañuelo y se quedó extático. Un par de ojos primero y otro par después siguieron los del ministro y entonces, como movida por un solo impulso, la gente se levantó y permaneció con la mirada fija en los tres muchachos que avanzaban por el pasillo. Tom a la cabeza, Joe a continuación y Huck, una ruina de colgantes andrajos, ¡deslizándose avergonzados hasta la parte trasera de la iglesia! Habían estado ocultos en la galería, oyendo el sermón de sus propios funerales. La tía Polly, Mary y los Harper se abalanzaron sobre sus familiares recobrados, los ahogaron a besos y derramaron acciones de gracias, mientras el pobre Huck se sentía confuso y azorado, no sabiendo exactamente qué hacer o dónde esconderse de aquellas miradas tan poco acogedoras. Titubeó y se disponía a retirarse, cuando Tom lo cogió y dijo:"}]$lira$::jsonb,
  980
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  49,
  'Los piratas asisten a sus propios funerales (2/2)',
  $lira$[{"type": "p", "text": "—Tía Polly, eso no es justo. Alguien tiene que alegrarse de ver a Huck."}, {"type": "p", "text": "—¡Pues claro que sí! ¡Yo me alegro mucho, pobre niño sin madre!"}, {"type": "p", "text": "Las cariñosas atenciones que le prodigó la tía Polly lo dejaron más confundido que antes. De repente el ministro gritó a pleno pulmón:"}, {"type": "p", "text": "—¡Alabado sea el Señor, de quien proviene toda bendición! ¡CANTAD!, y poned en el canto toda el alma."}, {"type": "p", "text": "Y así lo hicieron. El himno emergió con un estallido triunfante, y mientras hacía estremecer las vigas de la iglesia, Tom Sawyer el Pirata contemplaba los envidiosos rostros juveniles que lo rodeaban y se decía que aquel era el momento más halagador de su vida."}, {"type": "p", "text": "Cuando los engañados fieles salieron de la iglesia, dijeron que no les importaría que los pusieran en ridículo otra vez con tal de volver a oír el himno cantado de aquel modo."}, {"type": "p", "text": "Tom recibió más besos y palmadas aquel día —dado el carácter tornadizo de la tía Polly— que en un año; y apenas supo cuál de las dos cosas expresaba mejor el agradecimiento hacia Dios y el afecto hacia él."}]$lira$::jsonb,
  183
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  50,
  'El sueño de Tom (1/4)',
  $lira$[{"type": "p", "text": "Ese había sido el gran secreto de Tom: el proyecto de volver al pueblo con sus hermanos piratas para asistir a sus propios funerales. Bogaron sobre un tronco hacia la ribera del Missouri el sábado al anochecer, y desembarcaron cinco o seis millas más abajo del pueblo; durmieron en los bosques, al extremo del pueblo, hasta que casi fue de día, y entonces se deslizaron por callejas y andurriales poco frecuentados, hasta culminar su sueño en la galería de la iglesia, entre un caos de bancos sin patas. El lunes por la mañana, a la hora del desayuno, la tía Polly y Mary estaban muy cariñosas con Tom y muy atentas a sus deseos. La conversación de aquella mañana fue extraordinariamente larga. En un momento dado, la tía Polly dijo:"}, {"type": "p", "text": "—No diré yo que no sea una bella chanza, Tom, el tener a todo el mundo sufriendo durante casi una semana mientras vosotros os divertíais, pero es una lástima que hayas sido tan duro de corazón haciéndome padecer así. Si viniste sobre un tronco para tu funeral, también podrías haber venido a dejarme cualquier indicio de que no estabas muerto, sino que solo te habías escapado."}, {"type": "p", "text": "—Sí, podrías haberlo hecho, Tom —dijo Mary—; y creo que lo habrías hecho si se te hubiera ocurrido."}, {"type": "p", "text": "—¿Es cierto, Tom? —dijo la tía Polly con el rostro iluminado por la esperanza—. Dime: ¿lo habrías hecho de habérsete ocurrido?"}, {"type": "p", "text": "—Pues… no lo sé. Lo habría echado todo a perder."}, {"type": "p", "text": "—Tom, ya sabía yo que a eso se limitaba todo el amor que me tenías —dijo tía Polly con un tono ofendido que turbó al muchacho—. Aunque no lo hicieras, podrías haberte preocupado lo suficiente como para que se te ocurriera. Habría sido un gran consuelo para mí."}, {"type": "p", "text": "—Vamos, tía, no hubo mala intención —terció Mary—; ya conocemos la manera de ser de Tom; lleva siempre tanta prisa que nunca se acuerda de nada."}, {"type": "p", "text": "—Peor que peor. Sid se hubiese acordado. Y Sid, además, lo habría hecho. Algún día, cuando sea demasiado tarde, Tom, te acordarás y lamentarás no haberte preocupado más por mí, cuando te costaba tan poco."}, {"type": "p", "text": "—Vamos, tita, ya sabe que la quiero —dijo Tom."}, {"type": "p", "text": "—Lo sabría mejor si me lo demostraras."}, {"type": "p", "text": "—¡Ojalá me hubiese acordado! —dijo Tom con un tono arrepentido—; pero, de todos modos, soñé con usted. Algo es algo, ¿no?"}, {"type": "p", "text": "—No es mucho; un gato puede hacer otro tanto, pero más vale algo que nada. ¿Qué soñaste?"}, {"type": "p", "text": "—Pues el miércoles por la noche soñé que estaba usted sentada ahí, junto a la cama, y Sid estaba sentado al lado del cajón, y Mary pegada a él."}, {"type": "p", "text": "—Bien, así estábamos. Así nos sentamos siempre. Me complace que tus sueños se hayan tomado tanta molestia por nosotros."}, {"type": "p", "text": "—Y soñé que la madre de Joe Harper estaba aquí."}, {"type": "p", "text": "—¡Pues sí que estaba! ¿Soñaste algo más?"}, {"type": "p", "text": "—Muchas cosas. Pero ahora lo veo todo confuso."}, {"type": "p", "text": "—Bien, intenta acordarte, ¿de acuerdo?"}, {"type": "p", "text": "—Me parece como si el viento… hubiese apagado… la… la…"}, {"type": "p", "text": "—¡Sí, Tom, sí! El viento apagó algo. ¿Qué fue?"}, {"type": "p", "text": "Tom se presionó la frente con los dedos durante un angustioso minuto, y entonces dijo:"}, {"type": "p", "text": "—¡Ya está! ¡Ya está! Apagó la vela."}, {"type": "p", "text": "—¡Dios sea loado! Sigue, Tom, sigue."}, {"type": "p", "text": "—Y me parece que usted dijo: «Pero si veo que la puerta…»."}, {"type": "p", "text": "—Sigue, Tom."}, {"type": "p", "text": "—Déjeme pensar un momento, solo un momento. Sí, usted dijo que creía que la puerta estaba abierta."}, {"type": "p", "text": "—Es verdad que lo dije, tan verdad como que estoy aquí sentada, ¿no, Mary? Sigue."}, {"type": "p", "text": "—Y entonces… y entonces… no estoy muy seguro, pero me parece como si usted hubiese mandado a Sid a… a…"}, {"type": "p", "text": "—¿Adónde? ¿Adónde? ¿Qué le mandé?"}, {"type": "p", "text": "—Le mandó usted… Sí, le mandó cerrar la puerta."}, {"type": "p", "text": "—¡Válgame el cielo! En mi vida he oído nada parecido. No me digáis ahora que los sueños no son verdad. Sereny Harper va a saberlo antes de que yo tenga una hora más de vida. Me gustará ver qué dice, a pesar de todas sus tonterías sobre la superstición. Sigue, Tom."}, {"type": "p", "text": "—Y entonces se puso usted a llorar."}, {"type": "p", "text": "—Así es. Así es. Pero no era la primera vez que lloraba. Y entonces…"}, {"type": "p", "text": "—Entonces la señora Harper se puso a llorar y dijo que lo mismo ocurría con su Joe, y que ojalá no le hubiese zurrado por comerse la crema que ella misma había tirado…"}]$lira$::jsonb,
  718
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  51,
  'El sueño de Tom (2/4)',
  $lira$[{"type": "p", "text": "—¡Tom! El Espíritu estaba contigo. Estabas profetizando, eso es lo que hacías. ¡Válgame el cielo! Sigue, Tom."}, {"type": "p", "text": "—Luego Sid dijo… dijo…"}, {"type": "p", "text": "—No creo haber dicho nada —dijo Sid."}, {"type": "p", "text": "—Sí que dijiste algo —exclamó Mary."}, {"type": "p", "text": "—Callaos vosotros, y dejad hablar a Tom. ¿Qué dijo, Tom?"}, {"type": "p", "text": "—Dijo… creo que dijo que esperaba que me encontrase bien donde estaba, pero que si me hubiese portado mejor…"}, {"type": "p", "text": "—¿Estáis oyendo? Son sus mismas palabras."}, {"type": "p", "text": "—Y usted le mandó callar enojada."}, {"type": "p", "text": "—¡Así fue! Aquí debía de haber un ángel. En un sitio u otro había un ángel."}, {"type": "p", "text": "Y la señora Harper contó que Joe la había asustado con un cohete, y usted contó lo de Peter y el «bálsamo milagroso»."}, {"type": "p", "text": "—Es tan cierto como que vivo."}, {"type": "p", "text": "—Y entonces hablaron mucho rato de nuestra busca por el río y de celebrar los funerales el domingo, y entonces usted y la señora Harper se abrazaron llorando, y luego ella se marchó."}, {"type": "p", "text": "—Así ocurrió exactamente. Así ocurrió exactamente, tan cierto como que estoy aquí sentada. Tom, no habrías podido contarlo con más exactitud si lo hubieses visto. ¿Y después? Sigue, Tom."}, {"type": "p", "text": "—Me pareció que luego rezaba usted por mí, y podía verla y oír cada palabra que decía. Y se acostó usted, y yo sentía tanta pena que cogí un pedazo de corteza de sicomoro y escribí: «No estamos muertos, solo estamos haciendo de piratas», y lo dejé en la mesilla, junto a la vela; y entonces parecía usted tan buena, allí dormida, que me incliné y le di un beso."}, {"type": "p", "text": "—¿Eso hiciste, Tom, eso hiciste? Por eso te lo perdono todo."}, {"type": "p", "text": "Y dio un abrazo tan fuerte a Tom que le hizo sentirse el más vil de los canallas."}, {"type": "p", "text": "—Muy cariñoso, aunque solo se tratara de un… sueño —susurró Sid."}, {"type": "p", "text": "—Cállate, Sid. Las personas hacen en sueños lo mismo que harían despiertas. Toma esta manzana que guardaba para ti, en caso de que te encontraran, y ahora ve a la escuela. Estoy agradecida al buen Dios y Padre de todos nosotros por tenerte de nuevo. Él es paciente y misericordioso para los que creen en Él y siguen su palabra, aunque el cielo sabe que no lo merezco, pero si tan solo los merecedores recibieran sus bendiciones y su mano clemente en los malos pasos, pocos habría que sonriesen aquí, o entrasen en su reino de reposo a la llegada de la larga noche. A la escuela, Sid, Mary y Tom; ¡largo, que ya me habéis mareado bastante!"}, {"type": "p", "text": "Los muchachos se encaminaron hacia la escuela y la anciana se dirigió a casa de la señora Harper, dispuesta a vencer su materialismo con el maravilloso sueño de Tom. Sid era demasiado cuerdo para expresar la idea que tenía en la cabeza al salir de la casa. La idea era esta: «Es muy sospechoso. ¡Un sueño tan largo y sin una sola equivocación!»."}, {"type": "p", "text": "Tom se había transformado en un héroe. Ya no andaba saltando y encabritándose, sino que se movía con el digno balanceo que corresponde a un pirata que se sabe objeto de la admiración pública. Y en verdad era así; Tom fingía no ver las miradas ni oír los comentarios que levantaba a su paso, aunque fueran un deleite para su espíritu. Los chicos menores que él se congregaban en rebaños a sus talones, orgullosos de ser vistos con Tom y tolerados por él, como si fuera el timbalero a la cabeza de una procesión o el elefante que guía unas fieras hasta la ciudad. Los muchachos de su edad pretendían ignorar que había estado ausente; pero en realidad los consumía la envidia. Hubiesen dado cualquier cosa por tener aquella piel morena y curtida por el sol y la deslumbrante notoriedad del héroe; y Tom no hubiese renunciado a ella ni a cambio de un circo."}, {"type": "p", "text": "En la escuela los muchachos hablaban tanto de él y de Joe, y sus ojos traslucían una admiración tan elocuente, que los dos héroes no tardaron en ponerse insoportables. Empezaron a contar sus aventuras a los famélicos oyentes, pero solo empezaron; no era probable que las concluyeran, teniendo en cuenta su imaginación para suministrar material. Por último, cuando sacaron sus pipas y se pasearon echando serenas bocanadas de humo, alcanzaron la mismísima cúspide de la gloria."}]$lira$::jsonb,
  704
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  52,
  'El sueño de Tom (3/4)',
  $lira$[{"type": "p", "text": "Tom decidió que ya podía olvidarse de Becky Thatcher. Le bastaba la gloria. Viviría para la gloria. Como se había convertido en una persona de renombre, tal vez ella querría hacer las paces. Pues, bien, que lo intentara; descubriría que él podía mostrarse tan indiferente como otras personas. Poco después llegó Becky. Tom fingió que no la veía. Se alejó y se unió a un grupo de chicos y chicas, y comenzó a charlar. Pronto observó que Becky estaba corriendo alegremente de un lado a otro con la cara sonrojada y los ojos chispeantes, simulando estar ocupada en dar alcance a los compañeros y riendo alborozada cuando lograba atrapar a alguien; pero Tom se dio cuenta de que siempre atrapaba a alguien en sus proximidades y que en tales ocasiones le dirigía una mirada consciente. Aquello halagó su jactanciosa vanidad, de modo que en lugar de atraerlo, solo lo envaró más y redobló su propósito de demostrar que ignoraba la presencia de la muchacha. Al cabo de poco ella dejó de corretear y vagó indecisa de un lado para otro, suspirando unas veces y otras echando miradas furtivas y tristes hacia Tom. Observó entonces que Tom hablaba más con Amy que con las demás. Sintió un agudo pesar y al instante se quedó turbada e inquieta. Intentó alejarse, pero sus pies la traicionaron llevándola hacia el grupo. Entonces, con una vivacidad fingida, se dirigió a una muchacha que estaba casi al lado de Tom."}, {"type": "p", "text": "—Hola, Mary Austin. ¡Perezosa! ¿Por qué no viniste a la escuela dominical?"}, {"type": "p", "text": "—Sí que fui; ¿no me viste?"}, {"type": "p", "text": "—¿Estabas allí? ¿Dónde estabas sentada?"}, {"type": "p", "text": "—Estaba en la clase de la señorita Peter, como siempre. Yo a ti te vi."}, {"type": "p", "text": "—¿De veras? Vaya, es curioso que yo no te viera. Quería hablarte del picnic."}, {"type": "p", "text": "—¡Genial! ¿Quién lo organiza?"}, {"type": "p", "text": "—Mamá me dejará que os invite."}, {"type": "p", "text": "—Muy bien; espero poder ir."}, {"type": "p", "text": "—¡Claro que sí! El picnic es en mi honor. Dejará asistir a quien yo quiera, y me apetece que vengas."}, {"type": "p", "text": "—Es delicioso. ¿Y cuándo será?"}, {"type": "p", "text": "—Muy pronto. Tal vez durante las vacaciones."}, {"type": "p", "text": "—Será divertidísimo. ¿Invitarás a todos los chicos y chicas?"}, {"type": "p", "text": "—Sí, a todos los que sean amigos míos… o quieran serlo. —Y dirigió una mirada muy furtiva a Tom, pero este hablaba con Amy Lawrence de la terrible tempestad de la isla, y de cómo el rayo dejó el gran sicomoro «hecho astillas», mientras él «se encontraba a tres pies de distancia»."}, {"type": "p", "text": "—¿Me invitarás a mí? —dijo Gracie Miller."}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "—¿Y a mí? —dijo Sally Rogers."}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "—¿Y a mí también? —preguntó Susy Harper—. ¿Y a Joe?"}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "Y así sucesivamente, en medio de un gozoso batir de palmas, hasta que todo el grupo hubo rogado que lo invitaran menos Tom y Amy. Entonces Tom se alejó con frialdad, mientras seguía hablando, y se llevó a Amy. Los labios de Becky temblaron y las lágrimas asomaron a sus ojos; lo ocultó con una alegría forzada y continuó charlando, pero la vida había huido ya del picnic y de todo lo demás; se alejó tan pronto como pudo y se escondió para llorar y, como dicen las chicas, «desahogarse». Entonces se sentó pesarosa, con el orgullo herido, hasta que tocó la campana. Luego se levantó con un vengativo fulgor en sus ojos, dio una sacudida a sus trenzas y dijo que ya sabía lo que debía hacer."}, {"type": "p", "text": "Durante el recreo Tom siguió coqueteando con Amy con jubilosa jactancia. Y vagó de un lado a otro para encontrar a Becky y lacerarla con su maniobra. Al final la vio, pero el termómetro de su alegría sufrió un bajón repentino. Becky estaba sentada a sus anchas en un banquito de la parte posterior de la escuela, hojeando un libro de imágenes con Alfred Temple, y estaban tan absortos y tenían las cabezas tan juntas sobre el libro que no parecían darse cuenta de nada. Unos celos abrasadores recorrieron las venas de Tom. Se arrepintió de haber desperdiciado la oportunidad de reconciliación que le había ofrecido Becky. Se llamó a sí mismo estúpido y se dirigió todos los insultos que se le ocurrieron. Tenía ganas de llorar de despecho. Amy continuaba su alegre cháchara mientras caminaban, ya que su corazón rebosaba de júbilo, pero la lengua de Tom había perdido sus facultades. No oía lo que decía Amy, y cuando esta se paraba en una pausa expectante, solo podía balbucir una tosca frase que a veces era oportuna y otras no. No dejó de acercarse una y otra vez a la parte trasera de la escuela para abrasarse los ojos con el odioso espectáculo. No podía evitarlo. Y lo que lo volvía loco era pensar que Becky Thatcher no sospechaba siquiera que él se hallase en el mundo de los vivos. Pero ella lo veía y sabía que estaba ganando la batalla, y se alegraba de que sufriera como había sufrido ella."}]$lira$::jsonb,
  810
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  53,
  'El sueño de Tom (4/4)',
  $lira$[{"type": "p", "text": "El jovial parloteo de Amy se volvió insoportable. Tom mencionaba asuntos que tenía que atender, cosas que tenía que hacer, mientras el tiempo volaba. Pero era en vano; la muchacha seguía con sus gorjeos. Tom pensó: «¡Maldita sea! ¿No voy a desembarazarme nunca de ella?». Por último, tuvo que atender aquellos asuntos, y ella dijo ingenuamente que estaría «por allí» a la salida de la escuela. Tom se alejó a toda prisa, exasperado con ella."}, {"type": "p", "text": "—¡Precisamente este! —se decía Tom rechinando los dientes—. Entre todos los chicos de la ciudad, tenía que ser ese lechuguino de San Luis que se cree tan elegante y aristocrático. Muy bien, joven, te zurré la primera vez que te vi en el pueblo, y te zurraré otra vez. ¡Espera a que te atrape! Te voy a agarrar así y…"}, {"type": "p", "text": "Llevó a cabo todos los movimientos requeridos para hacer papilla a un muchacho imaginario, dando puñadas, patadas y empujones en el aire. «¿Qué te parece? ¿Has tenido bastante? Pues que te sirva de lección». Y así acabó la tunda imaginaria."}, {"type": "p", "text": "A mediodía Tom escapó hacia su casa. Su conciencia ya no podía soportar la agradecida felicidad de Amy, y sus celos no podían aguantar el otro infortunio. Becky reanudó la inspección de imágenes con Alfred, pero como transcurrían los minutos y Tom no se dejaba ver sufriendo por ello, su triunfo comenzó a nublarse y perdió el interés; siguieron la gravedad y la indiferencia, y luego la melancolía; dos o tres veces aguzó el oído ante unos pasos, pero fueron esperanzas vanas; Tom no apareció. Al final se sintió muy desgraciada y deseó no haber llevado el juego tan lejos. Cuando el pobre Alfred, al ver que la estaba perdiendo sin saber cómo, exclamó repetidamente: «¡Mira, esta imagen es preciosa!», Becky acabó perdiendo la paciencia y dijo:"}, {"type": "p", "text": "—No me molestes más. ¡No me importan un comino las imágenes! —Y rompió a llorar, se levantó y se fue."}, {"type": "p", "text": "Alfred la siguió y se disponía a intentar consolarla, cuando ella le atajó:"}, {"type": "p", "text": "—¿Es que no puedes dejarme sola? Te detesto."}, {"type": "p", "text": "Alfred se detuvo preguntándose qué error habría cometido, ya que Becky le dijo que mirarían las imágenes durante la pausa de mediodía. Becky se alejó llorando. Alfred entró en la escuela desierta. Estaba humillado y furioso. Enseguida adivinó toda la verdad: la muchacha lo había utilizado para desahogar su despecho hacia Tom Sawyer. Ese pensamiento no aminoró su odio hacia Tom. Deseó encontrar algún medio de perjudicar al muchacho sin comprometerse. Allí, a su alcance, estaba el libro de lectura de Tom. Aprovechó la ocasión. Lo abrió satisfecho en la lección de aquella tarde y llenó la página de manchas de tinta."}, {"type": "p", "text": "Becky, que estaba mirando el aula por una ventana, vio la maniobra y se alejó sin descubrir su presencia. Entonces emprendió el camino hacia su casa con la intención de encontrar a Tom y contárselo; Tom se lo agradecería y se arreglaría todo. Pero a medio camino de su casa cambió de parecer. Recordó indignada cómo la había tratado Tom cuando ella hablara del picnic y se avergonzó. Resolvió dejar que lo castigaran a causa del libro de lectura manchado y, además, odiarlo eternamente."}]$lira$::jsonb,
  529
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  54,
  '«Lo he hecho sin pensar»',
  $lira$[{"type": "p", "text": "Tom llegó a su casa muy abatido, y lo primero que le dijo su tía al entrar le demostró que había llevado sus pesares a un mercado poco acogedor."}, {"type": "p", "text": "—¡Tom, te voy a arrancar la piel!"}, {"type": "p", "text": "—Tita, ¿qué he hecho?"}, {"type": "p", "text": "—Pues bastante. He ido a visitar a Sereny Harper, como una vieja tonta, esperando hacerle creer todas las boberías de aquel sueño, y descubro, ¡prepárate!, que ha sabido por Joe que aquella noche viniste aquí y oíste toda la conversación. Tom, no sé adónde puede llegar un muchacho que obra de este modo. ¡Cuánto me duele pensar que has dejado que hiciera el ridículo yendo a ver a Sereny Harper, sin decirme una palabra!"}, {"type": "p", "text": "Tom vio entonces el asunto bajo otra luz. Su agudeza de la mañana le había parecido entonces una chanza estupenda e ingeniosa. De pronto solo le parecía mezquina y vil. Agachó la cabeza y no supo qué decir durante un momento. Después exclamó:"}, {"type": "p", "text": "—Tita, ojalá no lo hubiera hecho, pero lo he hecho sin pensar."}, {"type": "p", "text": "—¡Ay, niño, jamás piensas! Solo piensas en ti. Se te ocurrió venir hasta aquí desde la isla de Jackson, de noche, para reírte de nuestras penas, y se te ocurrió burlarte de mí con la mentira del sueño; pero nunca has pensado en compadecerte de nosotros y en ahorrarnos tanto pesar."}, {"type": "p", "text": "—Tía, sé que obré mal, pero no tenía esa intención. No la tenía, de veras. Y, además, aquella noche no vine aquí para reírme de usted."}, {"type": "p", "text": "—Pues ¿a qué viniste?"}, {"type": "p", "text": "—A decirle que no se preocupara por nosotros, porque no nos habíamos ahogado."}, {"type": "p", "text": "—Tom, Tom, sería el alma más agradecida del mundo si pudiese creer que se te ocurrió esta idea, pero tú sabes que jamás se te ocurrió… y yo también lo sé, Tom."}, {"type": "p", "text": "—De veras, de veras que lo pensé, tita, ¡que me muera si es mentira!"}, {"type": "p", "text": "—No mientas más, Tom, no mientas más. Solo consigues empeorar las cosas."}, {"type": "p", "text": "—No es mentira, tía, es la verdad. Yo no quería que usted se afligiese; por eso vine."}, {"type": "p", "text": "—Daría el mundo entero por creerte; eso te redimiría de un buen número de pecados, Tom. Casi me alegraría de que hubieses escapado y obrado tan mal. Pero es una locura; si no, di: ¿por qué no me advertiste?"}, {"type": "p", "text": "—Porque empezaron a hablar de los funerales, y entonces me entusiasmó la idea de escondernos en la iglesia, y no logré decidirme a echarla a perder. Así que me guardé la corteza en el bolsillo y no dije nada."}, {"type": "p", "text": "—¿Qué corteza?"}, {"type": "p", "text": "—La corteza donde le escribí que estábamos haciendo de piratas. ¡Ojalá la hubiese despertado entonces, cuando la besé, ojalá!"}, {"type": "p", "text": "Los severos rasgos del rostro de la tía Polly se suavizaron y una súbita ternura le iluminó los ojos."}, {"type": "p", "text": "—Pero ¿me besaste, Tom?"}, {"type": "p", "text": "—Claro que sí."}, {"type": "p", "text": "—¿Estás seguro, Tom?"}, {"type": "p", "text": "—Pues claro que sí, tía, bien seguro."}, {"type": "p", "text": "—¿Por qué me besaste, Tom?"}, {"type": "p", "text": "—Porque la quiero, y estaba usted llorando y yo sentía mucha pena."}, {"type": "p", "text": "Las palabras parecían sinceras. La anciana no pudo disimular un temblor en la voz cuando dijo:"}, {"type": "p", "text": "—Bésame otra vez, Tom… y ahora vete a la escuela, y no me fastidies más."}, {"type": "p", "text": "En cuanto Tom se marchó, la tía Polly corrió al armario y sacó la chaqueta destrozada que había llevado Tom en sus piraterías. Entonces se detuvo, con la prenda en la mano, y dijo para sí:"}, {"type": "p", "text": "—No, no me atrevo. Pobrecillo, supongo que habrá mentido, pero bendita sea su mentira, ya que tanto consuelo me da. Espero que el Señor… Sé que el Señor lo perdonará, porque se lo dictó su buen corazón. Y no quiero descubrir que es una mentira. No, no quiero saberlo."}, {"type": "p", "text": "Dejó a un lado la chaqueta y se quedó pensativa durante un minuto. Alargó la mano dos veces para coger de nuevo la prenda, y se refrenó dos veces. Se aventuró otra vez y se convenció al pensar: «Es una mentira bien intencionada, y una mentira bien intencionada no debe causarme pesadumbre». Registró el bolsillo de la chaqueta. Un instante después leía el trozo de corteza de Tom a través de un río de lágrimas y decía:"}, {"type": "p", "text": "—¡Ahora perdonaría al muchacho, aunque hubiera pecado un millón de veces!"}]$lira$::jsonb,
  694
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  55,
  'Tom carga con el castigo de Becky (1/2)',
  $lira$[{"type": "p", "text": "Algo en el modo de besarlo de la tía Polly desvaneció la tristeza de Tom y le hizo sentirse de nuevo animado y alegre. Se dirigió a la escuela y tuvo la suerte de tropezarse con Becky Thatcher delante de Meadow Lane. Su ánimo determinaba siempre su manera de proceder. Sin vacilar ni un instante, corrió hacia ella y le dijo:"}, {"type": "p", "text": "—Hoy me he portado de un modo muy vil, Becky, y lo siento. Jamás, jamás volveré a portarme así mientras viva; hagamos las paces, ¿quieres?"}, {"type": "p", "text": "La niña se detuvo y lo miró desdeñosamente."}, {"type": "p", "text": "—Le agradeceré que se ocupe de sus asuntos, señor Thomas Sawyer. No pienso dirigirle más la palabra."}, {"type": "p", "text": "Sin decir ni una palabra más prosiguió su camino. Tom se quedó tan aturdido que ni siquiera tuvo presencia de ánimo para decir: «¿Y a quién le importa esto, señorita Presumida?» hasta que hubo pasado el momento oportuno, así que no dijo nada. Sin embargo, se enfureció más de la cuenta. Entró en el patio de la escuela, deseando que Becky hubiera sido un muchacho e imaginando cómo la trataría de haber sido un chico. Al cabo de poco se encontró con ella y al cruzársela soltó una hiriente burla. Ella le contestó a gritos y la furiosa ruptura fue absoluta. Becky, en su encendido resentimiento, creía que apenas podía esperar la hora de entrar en clase, consumida por la impaciencia de ver a Tom azotado a causa del libro de lectura. Si tuvo alguna vaga intención de descubrir a Alfred Temple, la ofensiva burla de Tom la desvaneció por completo."}, {"type": "p", "text": "La pobre niña no sabía cuán cerca estaba ella también de sufrir un tropiezo. El maestro, el señor Dobbins, había llegado a una edad avanzada con una ambición insatisfecha. Su mayor deseo era ser médico, pero la pobreza había decretado que no pasaría de maestro de escuela. Cada día sacaba de su pupitre un libro misterioso y se enfrascaba en su lectura mientras no se recitaba la lección. Guardaba el libro bajo llave. No había un solo chiquillo en la escuela que no se muriese de ganas de echarle una ojeada, pero la ocasión no se presentaba nunca. Cada chico y cada chica tenía su propia teoría acerca de la naturaleza de aquel libro; pero no había dos teorías iguales, y no había manera de llegar a una idea concreta."}, {"type": "p", "text": "Cuando Becky pasó junto al pupitre, que se encontraba cerca de la puerta, advirtió que la llave estaba en la cerradura. Era una oportunidad única. Echó un vistazo en derredor; se encontró sola y un momento después tenía el libro entre las manos. El título que aparecía en la primera página, Anatomía del profesor Tal, no le procuró información alguna, así que comenzó a pasar las páginas. De pronto encontró una hermosa lámina de colores que representaba una figura humana en cueros. En aquel instante se proyectó una sombra sobre la página, Tom Sawyer atravesó el umbral y echó una ojeada a la lámina. Becky dio un fuerte tirón al libro para cerrarlo, y tuvo la mala suerte de rasgar el grabado hasta media página. Metió el volumen en el pupitre, giró la llave y rompió a llorar avergonzada y temerosa."}, {"type": "p", "text": "—Tom Sawyer, eres la persona más vil del mundo, acechando a otra persona para ver qué mira."}, {"type": "p", "text": "—¿Cómo iba a saber yo que estabas mirando algo?"}, {"type": "p", "text": "—Tendrías que avergonzarte de ti mismo, Tom Sawyer; sé que me delatarás, y ¿qué haré entonces, qué haré? Me azotarán, y será la primera vez que me peguen en la escuela. —Después, pateando con impaciencia en el suelo, dijo—: Eres vil y rastrero. Yo sé que va a ocurrir algo. Espera y verás. ¡Eres odioso, odioso! —Y se marchó hecha un mar de lágrimas."}, {"type": "p", "text": "Tom se quedó inmóvil, un poco aturdido por esta embestida. Al cabo de poco se dijo:"}, {"type": "p", "text": "—¡Qué curiosas tontuelas son las chicas! No la han azotado nunca en la escuela. ¡Boberías! ¿Qué es una azotaina? Bah, es propio de una chica: piel fina y corazón de polluelo. Bueno, por supuesto que no voy a delatar a esa tontuela ante el señor Dobbins, porque existen otras maneras de vengarme menos ruines; pero ¿qué ocurrirá? El viejo Dobbins preguntará quién ha roto el libro. Nadie contestará. Entonces empleará el procedimiento de siempre, preguntar primero a uno y luego a otro, y cuando llegue a la chica culpable lo sabrá, sin que se lo diga nadie. Las caras de las muchachas se delatan siempre. No saben disimular. Y recibirá la azotaina. En mal paso se ha metido Becky Thatcher, pues no hay ninguna salida."}, {"type": "p", "text": "—Tom caviló unos momentos más y luego añadió—: Al fin y al cabo, a ella le gustaría verme en un aprieto así, ¡qué se fastidie!"}, {"type": "p", "text": "Tom fue a unirse al enjambre de ruidosos escolares en el patio. Al cabo de unos momentos llegó el maestro y comenzó la clase. Tom no sentía gran interés por sus estudios. Cada vez que dirigía la mirada al lado de las chicas, el rostro de Becky lo llenaba de turbación. Teniendo en cuenta lo sucedido, él no quería compadecerla y, sin embargo, tampoco experimentaba alegría alguna. No sentía una exaltación que fuese realmente digna de ese nombre. Poco después se descubrió el libro de lectura manchado, y Tom se quedó absorto en sus propios asuntos durante el rato que siguió. Becky salió del letargo de su infortunio y mostró un gran interés por los procedimientos penales. No confiaba en que Tom saliese del apuro negando que había manchado el libro de tinta, y tenía razón. La negativa, al parecer, solo empeoró la situación de Tom. Becky suponía que debía alegrarse de ello, y trató de creer que se alegraba, pero descubrió que no estaba muy segura. Cuando llegó lo peor, sintió el impulso de levantarse y delatar a Alfred Temple, pero hizo un esfuerzo y se obligó a permanecer quieta, diciéndose a sí misma que «él dirá que he rasgado la imagen del libro. ¡No diría una palabra, ni para salvarle la vida!». Tom recibió una azotaina y volvió a su sitio no del todo descorazonado, pues creía muy posible que él mismo hubiese vertido la tinta sobre el libro sin darse cuenta, en alguna de sus impetuosas gestas; lo había negado por pura fórmula y porque era costumbre, y había insistido por una cuestión de principios. Una hora después el maestro daba cabezadas en su trono y el murmullo de los estudios entorpecía el aire. Poco después el señor Dobbins se desperezó, bostezó, luego abrió el pupitre y cogió el libro, pero se mostró indeciso entre sacarlo o dejarlo. La mayoría de los alumnos dirigieron una lánguida mirada, pero había dos entre ellos que observaban sus movimientos con detenimiento. El señor Dobbins manoseó el libro distraídamente unos instantes, luego lo sacó y se acomodó en su asiento para leer. Tom echó un vistazo a Becky. En una ocasión había visto un conejillo desvalido y atrapado, con un fusil apuntándole en la cabeza, que tenía el mismo aspecto. Tom se olvidó al instante de su disputa con ella. ¡Tenía que hacer algo en un abrir y cerrar de ojos! Pero la misma inminencia de la catástrofe le paralizaba la inventiva. Al fin tuvo una inspiración. Se apoderaría del libro por sorpresa, saltaría hacia la puerta y emprendería la fuga. Pero su resolución titubeó durante un breve instante, y perdió la oportunidad: el maestro ya estaba abriendo el libro. ¡Ojalá la desperdiciada ocasión hubiera vuelto a presentársele! Pero era demasiado tarde. Ya no había salvación para Becky, pensó Tom. Un momento después el maestro se encaraba con los alumnos. Todos los ojos se agacharon ante su mirada. Había algo en ella que amedrentaba incluso a los inocentes. Reinó el silencio el tiempo de contar hasta diez, mientras el maestro se iba enfureciendo."}]$lira$::jsonb,
  1301
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  56,
  'Tom carga con el castigo de Becky (2/2)',
  $lira$[{"type": "p", "text": "—¿Quién ha rasgado este libro? —preguntó."}, {"type": "p", "text": "Se hizo el silencio más absoluto. Hubiera podido oírse la caída de un alfiler. El maestro escudriñaba un rostro tras otro en busca de indicios culpables."}, {"type": "p", "text": "—Benjamin Rogers, ¿has rasgado este libro?"}, {"type": "p", "text": "Negativa. Otra pausa."}, {"type": "p", "text": "—Joseph Harper, ¿lo has hecho tú?"}, {"type": "p", "text": "Otra negativa. La inquietud de Tom iba en aumento bajo la lenta tortura de ese procedimiento. El maestro examinó las hileras de muchachos, caviló un rato y luego se dirigió a las chicas."}, {"type": "p", "text": "—¿Amy Lawrence?"}, {"type": "p", "text": "Brusco movimiento de cabeza."}, {"type": "p", "text": "—¿Gracie Miller?"}, {"type": "p", "text": "Mismo gesto."}, {"type": "p", "text": "—Susan Harper, ¿lo has hecho tú?"}, {"type": "p", "text": "Otra negativa. La siguiente muchacha era Becky Thatcher. Tom temblaba de pies a cabeza, agitado ante la desesperada situación."}, {"type": "p", "text": "—Rebecca Thatcher —Tom le miró el rostro: estaba blanca de terror—, ¿has rasgado… no, mírame a la cara —sus manitas se alzaron suplicantes—, has rasgado el libro?"}, {"type": "p", "text": "Una idea atravesó como un rayo el cerebro de Tom. Se puso en pie de un salto y gritó:"}, {"type": "p", "text": "—¡He sido yo!"}, {"type": "p", "text": "Todos los alumnos se quedaron perplejos ante aquella increíble locura. Tom permaneció un instante inmóvil concentrando sus facultades dispersas, y cuando se adelantó para recibir su castigo, la sorpresa, la gratitud y la adoración que derramaron sobre él los ojos de la pobre Becky le parecieron la paga suficiente de cien azotainas. Inspirado por el esplendor de su propio acto, recibió sin una queja la paliza más inhumana que había administrado el señor Dobbins en su vida, y también recibió con indiferencia la orden, cruelmente añadida, de quedarse dos horas más una vez terminadas las clases, pues sabía quién le esperaría fuera hasta que hubiese terminado su cautiverio, sin creer tampoco que aquel largo intervalo era tiempo perdido."}, {"type": "p", "text": "Aquella noche Tom se acostó planeando su venganza contra Alfred Temple; ya que, avergonzada y contrita, Becky se lo contó todo, sin omitir su propia traición; pero hasta los anhelos de venganza tuvieron que dar paso enseguida a pensamientos más agradables, y se durmió al fin con las últimas palabras de Becky resonando dulcemente en su oído."}, {"type": "p", "text": "—Tom, ¿cómo has podido ser tan noble?"}]$lira$::jsonb,
  346
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  57,
  'Elocuencia, y la dorada cúpula del profesor (1/3)',
  $lira$[{"type": "p", "text": "Se aproximaban las vacaciones. El maestro de escuela, que siempre era severo, mostraba más severidad y exigencia que nunca, pues quería que los alumnos se lucieran el día de los exámenes. La vara y la palmeta estaban a la sazón raramente ociosas, por lo menos entre los escolares más pequeños. Solo los muchachos mayores y las señoritas de dieciocho y veinte años escapaban a los azotes. Además, los azotes que propinaba el señor Dobbins eran muy vigorosos, pues aunque bajo la peluca tuviera la cabeza perfectamente calva y brillante, y fuera un hombre entrado en años, sus músculos no mostraban el menor signo de fatiga. A medida que se aproximaba el gran día, toda la tiranía que anidaba en él subía a la superficie; parecía encontrar un rencoroso placer castigando los menores descuidos. La consecuencia era que los pequeños pasaban los días sumidos en el terror y el sufrimiento, y las noches planeando venganzas. No desperdiciaban la ocasión de jugarle una mala pasada. Pero el maestro les llevaba siempre ventaja. La retribución que seguía a cada éxito vengativo era tan arrolladora y majestuosa que los muchachos se retiraban siempre del campo maltrechos y derrotados. Al final conspiraron juntos y se les ocurrió un plan que prometía una deslumbrante victoria. Enzarzaron en el complot al hijo del pintor de rótulos, le explicaron el proyecto y le pidieron que participara. Este tenía sus propias razones para aceptar, pues el maestro se hospedaba en casa de su padre y había dado al muchacho amplios motivos para odiarle. La esposa del maestro tenía que marcharse al campo unos días, de modo que nada estorbaría el plan; el maestro se preparaba siempre para las grandes ocasiones cogiendo una borrachera, y el hijo del pintor de rótulos dijo que, la tarde de los exámenes, cuando el dómine se encontrase en el estado ideal, él «arreglaría la cosa», mientras dormitase en su silla; luego lo despertaría a la hora exacta y correría hacia la escuela. Al fin llegó el día del interesante acontecimiento. A las ocho de la noche la escuela estaba muy iluminada y adornada con guirnaldas de flores y hojas. El maestro estaba entronizado en su amplio asiento, sobre una alta plataforma, con la pizarra a su espalda. Tres hileras de bancos a cada lado y otras seis hileras enfrente de él estaban ocupados por los dignatarios de la ciudad y por los familiares de los alumnos; hileras de chiquillos, aseados y vestidos hasta sentirse incómodos; hileras de zafios muchachotes; bancos níveos de muchachas y señoritas vestidas de linón y muselina, muy conscientes de sus brazos desnudos, de las antiguas alhajas de sus abuelas, de los trocitos de cinta rosa y azul y de las flores que lucían en el cabello. El resto de la sala estaba ocupada por los alumnos que no participaban en los exámenes. Empezaron los ejercicios. Un niño muy pequeño se puso en pie y recitó con timidez: «Poco podían suponer ustedes verme a mi edad dirigiéndome a un público», etc., acompañándose de una gesticulación tan penosamente exacta y espasmódica que parecía propia de una máquina, suponiendo que la máquina estuviera algo descompuesta. Llegó al final sin tropiezos, aunque con un pavor cruel, recibió los aplausos al hacer un saludo ensayado y se retiró."}, {"type": "p", "text": "Una vergonzosa muchachita tartamudeó «María tenía una ovejita», etc., ejecutó un saludo que partía el alma, recibió su tanda de aplausos y se sentó ruborizada y feliz."}, {"type": "p", "text": "Tom Sawyer avanzó con arrogante confianza y se aventuró con el inextinguible e indestructible discurso «Dadme la libertad o la muerte», con bello ímpetu y frenética gesticulación, y se quedó mudo a la mitad. Un tétrico pavor se apoderó de él; le temblaban las piernas y casi se ahogaba. Cierto es que tenía a su favor la manifiesta simpatía del público, pero tenía también el silencio del público, que era todavía peor que su simpatía. El maestro frunció las cejas y aquello completó el desastre. Tom luchó unos instantes y luego se retiró derrotado. Hubo un débil conato de aplauso que se extinguió al nacer. Luego siguió «El muchacho estaba sobre el puente en llamas», así como «El asirio llegó» y otras perlas declamatorias. Luego tuvieron lugar ejercicios de lectura y un torneo de ortografía. La exigua clase de latín recitó con honor. Luego le llegó el turno a la flor del programa: las «composiciones» originales de las señoritas. Cada una por turno se adelantó hasta el borde de la plataforma, carraspeó, alzó su manuscrito (atado con una primorosa cinta) y comenzó la lectura, cuidando especialmente la «expresión» y la puntuación. Los temas eran los mismos que habían tratado ya en similares ocasiones las madres de las señoritas, las abuelas y todos los antepasados de sexo femenino hasta las Cruzadas. Los títulos eran: «Amistad»; «Recuerdos de otro tiempo»; «La religión en la historia»; «Tierra de ensueño»; «Las ventajas de la cultura»; «Formas de gobierno político comparadas y contrastadas»; «Melancolía»; «Amor filial»; «Anhelos del corazón», etc."}]$lira$::jsonb,
  825
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  58,
  'Elocuencia, y la dorada cúpula del profesor (2/3)',
  $lira$[{"type": "p", "text": "Un rasgo característico de esas composiciones era su intencionada melancolía; otro, el chorro pródigo y opulento de «fino lenguaje»; otro, la tendencia a repetir palabras y frases especialmente apreciadas, hasta agotarlas del todo; y una particularidad que las distinguía y echaba a perder notablemente era el inveterado e intolerable sermón que meneaba su estropeado rabo al final de cada una de ellas. Cualquiera que fuese el tema, se hacía un torturador esfuerzo del cerebro para rematarlo en un sentido u otro que el espíritu moral y religioso pudiera considerar edificante. La evidente falta de sinceridad de esos sermones no era suficiente para conseguir que la moda de pronunciarlos se desterrara de las escuelas, ni es suficiente hoy día; ni tal vez sea suficiente jamás, mientras exista el mundo. No existe ninguna escuela en nuestro país donde las señoritas no se sientan obligadas a terminar sus composiciones con un sermón; y veréis que el sermón de la muchacha más frívola y menos religiosa de la escuela es siempre el más largo y piadoso. Pero dejémoslo ahí, porque la verdad casera es desabrida."}, {"type": "p", "text": "Volvamos a los exámenes. La primera composición que se leyó fue la titulada «¿Es esto, pues, la vida?». Tal vez el lector pueda soportar un extracto de ella:"}, {"type": "p", "text": "En el monótono transcurso de la vida, ¡con qué deleitosas emociones anhela una mente joven una escena de fiesta! La imaginación está ocupada esbozando gozosos cuadros de rosados tonos. En su fantasía, la voluptuosa devota de la moda se ve a sí misma entre la festiva multitud, «observada por todos». Su grácil figura, envuelta en níveas telas, remolinea a través de los laberintos de la alegre danza; sus ojos son los más brillantes y sus pasos los más ligeros de la jubilosa reunión."}, {"type": "p", "text": "Con tales deliciosas fantasías vuela el tiempo, y llega la esperada hora de entrar en el mundo elisio, del cual ella tiene tantos sueños brillantes. ¡Qué mágicas le parecen las cosas a su hechizada mirada! Cada nueva escena es más encantadora que la anterior. Pero no tarda en descubrir que bajo aquella hermosa apariencia todo es vanidad; los halagos que una vez le hechizaron el alma de pronto le rechinan con aspereza en los oídos; la sala de baile ha perdido sus encantos, y se aleja con la salud mermada y el corazón amargado, convencida de que los placeres terrenos no pueden colmar las ansias de su alma."}, {"type": "p", "text": "Y así sucesivamente. En el transcurso de la lectura, de vez en cuando se oía un murmullo de deleite, acompañado de exclamaciones susurradas apenas: «¡Qué hermoso!», «¡Qué elocuente!», «¡Es verdad!», etc., y después de que concluyera con un sermón sumamente aflictivo, los aplausos fueron entusiastas. Luego se levantó una muchacha flaca y melancólica, cuyo rostro tenía la «interesante» palidez que causan las píldoras y la propensión a las indigestiones, y leyó un «poema». Bastarán dos estrofas:"}, {"type": "h", "text": "El Adiós A Alabama De Una Muchacha De Missouri"}, {"type": "p", "text": "¡Adiós, Alabama! ¡Dulce tierra adorada"}, {"type": "p", "text": "que contra mis deseos tengo que abandonar!"}, {"type": "p", "text": "Tus recuerdos acuden a mi frente abrasada,"}, {"type": "p", "text": "mi corazón llora, presa de un hondo pesar."}, {"type": "p", "text": "Deambulé por tus bosques de flores olorosas,"}, {"type": "p", "text": "y junto a la corriente del Tallapoosa leí horas y horas,"}, {"type": "p", "text": "y oí del Tallassce las olas belicosas,"}, {"type": "p", "text": "y en el Coosa admiré los rayos de la aurora."}, {"type": "p", "text": "El peso de mi grávido corazón no me avergüenza"}, {"type": "p", "text": "ni me humillan mis lágrimas que fluyen como un mar."}, {"type": "p", "text": "Pues la que abandono no es una tierra extraña,"}, {"type": "p", "text": "ni a extranjeros libro mi pesar."}, {"type": "p", "text": "¡Hogar acogedor!, en este estado te hallas;"}, {"type": "p", "text": "un estado cuyos valles se alejan de mí."}, {"type": "p", "text": "Mi corazón se enfría, mis ojos y mi tête,"}, {"type": "p", "text": "todo, porque ¡Alabama querida!, los apartó de ti."}, {"type": "p", "text": "Muy pocos sabían qué significaba tête, pero, con todo, el poema gustó muchísimo."}, {"type": "p", "text": "Después apareció una señorita de tez oscura, de ojos y de cabellos negros, que guardó un impresionante momento de silencio, asumió una actitud trágica y comenzó a leer en un tono solemne y mesurado."}, {"type": "h", "text": "Una Visión"}, {"type": "p", "text": "Sombría y tormentosa era la noche. Alrededor del divino trono, en las alturas, no parpadeaba ni una sola estrella, pero las hondas detonaciones del pesado trueno vibraban sin cesar en el oído, mientras el terrorífico rayo se entregaba a una furiosa orgía en los nebulosos aposentos del firmamento, pareciendo desdeñar el poder ejercido sobre sus terrores por el ilustre Franklin. Hasta los vientos ruidosos vinieron unánimemente de sus místicas moradas, y bramaron a un lado y a otro como si quisieran contribuir al horror de la escena. En aquella hora tan oscura y triste, mi espíritu suspiraba por una humana simpatía; pero entonces: Mi más querida amiga, mi consejera y guía,"}]$lira$::jsonb,
  773
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  59,
  'Elocuencia, y la dorada cúpula del profesor (3/3)',
  $lira$[{"type": "p", "text": "la alegría en mis penas, hacia mí venía."}, {"type": "p", "text": "Se movía como uno de esos brillantes seres imaginados en los soleados paseos de un Edén fantástico por mentes románticas y jóvenes, cual reina de hermosura a quien solo adornara su propia belleza trascendente. Tan leve era su paso que no hacía el menor ruido, y a no ser por la mágica impresión que producía su benigno contacto, hubiera pasado inadvertida, omisa, como otras bellezas llenas de modestia. Una rara tristeza reposaba en sus rasgos, como heladas lágrimas sobre el manto de diciembre, al señalarme los belicosos elementos del exterior e invitarme a contemplar los dos seres que indicaba."}, {"type": "p", "text": "Aquella pesadilla ocupó unas diez páginas de manuscrito y culminó en un sermón que destruía tanto cualquier esperanza para los no presbiterianos que logró el primer premio. Esa composición se consideró el más bello esfuerzo de la velada. El alcalde del pueblo, al entregar el premio a la autora, pronunció un fervoroso discurso en el que dijo que era la composición más «elocuente» que había oído en su vida y que el mismo Daniel Webster no hubiese desdeñado firmarla."}, {"type": "p", "text": "Cabe observar, de paso, que el número de composiciones en que se prodigó la palabra «bellísimo» y se aludió a la experiencia humana como una «página de la vida» sobrepasó el porcentaje habitual. Entonces el maestro, suavizado casi hasta los límites de la jovialidad, retiró a un lado su asiento, volvió la espalda al público y se puso a dibujar un mapa de América en el encerado para los ejercicios de la clase de geografía. Pero su mano vacilante no logró una obra perfecta, y se oyeron unas risitas ahogadas entre el público. El maestro sospechó el motivo y se dispuso a enmendar el yerro. Borró las líneas y las trazó de nuevo; pero solo consiguió desviarlas más que antes, y las risitas se volvieron más intensas. Entonces concentró toda su atención en la labor, dispuesto a no dejarse intimidar. Notó que las miradas estaban fijas en él; imaginó que lograba su objeto, pero las risas continuaron; de hecho, era evidente que aumentaban. Y con razón. En el techo había un desván con un escotillón que daba sobre su cabeza; y a través de esa abertura se asomaba un gato, colgado de una cuerda por las patas traseras; llevaba atadas la cabeza y las quijadas con un trapo para impedir que maullase; en su lento descenso se encorvaba hacia arriba y se aferraba a la cuerda o se balanceaba hacia abajo, dando zarpazos en el aire intangible. Las risas fueron subiendo de tono. El gato estaba a seis pulgadas de la cabeza del absorto profesor, bajó un poco más, un poco más, y le agarró la peluca con sus zarpas desesperadas, se aferró a ella y de un tirón fue izado al desván con el trofeo aún en su poder. ¡Y cómo irradió la luz de la calva mollera del profesor…! ¡El chico del pintor de rótulos la había dorado!"}, {"type": "p", "text": "La fiesta quedó interrumpida al instante. Los muchachos se habían vengado. Acababan de empezar las vacaciones."}]$lira$::jsonb,
  512
);
